#!/usr/bin/env node
// The pubid-scheme URN corpus probe (pubid-ts#161) — the TS twin of the
// ruby contract wave's corpus run and of spec/pubid/pubid_urn_contract_spec.rb.
//
// Over every corpus case carrying an identifier hash, per flavor:
//   (a) EMIT:    encode(hash) equals the ruby reference's URN byte-exactly
//                (when PARITY_JSON, the fixture generated by the ruby probe);
//   (b) ROUND-TRIP: decode(urn) rebuilds the hash (canonical-JSON equal);
//   (c) BUILD:   parse(urn) rebuilds the identifier through fromHash and
//                re-encodes to exactly the same URN (the canonical gate);
//   (d) INJECTIVE: two different hashes never share a URN;
//   (e) PATH-SAFE: only [A-Za-z0-9._~,()\-:] and ":", no empty segment;
//   (f) SLUG:    toSlug/fromSlug round-trip the identifier hash.
//
//   npm run build && node scripts/probe-pubid-urn.mjs
//
// env:
//   TESTSUITE_DIR  a pubid-testsuite tests/ tree (default ../pubid-testsuite/tests)
//   PARITY_JSON    the ruby-side probe output (default: absent — parity check skipped)
import { readdirSync, readFileSync, existsSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { gunzipSync } from "node:zlib";
import { parse as parseYaml } from "yaml";
import {
  PREFIX,
  Decoder,
  generate,
  parse,
  toSlug,
  fromSlug,
} from "../dist/pubid-urn/index.js";
// Flavor registration (resolveType) — the side-effect import every
// parse-side consumer needs.
import "../dist/flavors/index.js";
import { resolveType } from "../dist/model/identifier.js";

const testsDir = resolve(process.env["TESTSUITE_DIR"] ?? "../pubid-testsuite/tests");
const parityPath = process.env["PARITY_JSON"];
const parity = parityPath && existsSync(parityPath)
  ? JSON.parse(readFileSync(parityPath, "utf8"))
  : undefined;
const SLOW = process.env["PROBE_SKIP_BUILD"] === "1";

/**
 * The psych-vs-yaml-package wire divergence (YAML 1.1 keeps
 * `102E-42` a String, the 1.2 core schema floats it): the ruby hash is
 * the reference wire form, so rows recorded in the fixture's
 * hashOverrides encode from the ruby hash, not the npm-loaded one.
 */
const fixturePath = resolve("test/fixtures/pubid-urn-parity.json.gz");
const hashOverrides = existsSync(fixturePath)
  ? (JSON.parse(gunzipSync(readFileSync(fixturePath)).toString("utf8")).hashOverrides ?? {})
  : {};

/**
 * Flavors whose corpus rows emit, decode and round-trip but whose
 * identifier class is not ported yet (no TS model to fromHash into), so
 * the canonical rebuild (c) cannot run for them. Landing the flavor's
 * model removes it from this list — the probe fails on an unknown
 * flavor here, so a stale entry cannot rot.
 */
const BUILD_PENDING = new Set([
  "ccsds",
  // The testsuite's SAE corpus round landed identifier hashes for the
  // flavor (testsuite 1ac4ec81); the URN schema table is ported but the
  // SAE identifier model is not, so the rebuild pends on it like ccsds.
  "sae",
]);

/**
 * Rows where the canonical rebuild (c) is pending on the port's own
 * pinned quirks, not on the codec: the TS nist model keeps the
 * yaml-package float for exponential spellings (test/grammar-nist.test.ts
 * "The Ruby YAML float quirk survives in the wire hash"), so a rebuilt
 * id re-encodes the float and fails the canonical compare. Ruby keeps
 * the String, and the URN itself already carries it byte-exactly —
 * (a),(b),(d),(e) run for these rows too.
 */
const REBUILD_PENDING = new Set([
  "nist.commercial_standard.1870",
  "nist.commercial_standard.1951",
  "nist.commercial_standard.2046",
  "nist.commercial_standard.2067",
  "nist.commercial_standard.2079",
  "nist.commercial_standard.2123",
]);

const canon = (node) => {
  if (Array.isArray(node)) return node.map(canon);
  if (node !== null && typeof node === "object") {
    const out = {};
    for (const key of Object.keys(node).sort()) out[key] = canon(node[key]);
    return out;
  }
  return node;
};
const same = (a, b) => JSON.stringify(canon(a)) === JSON.stringify(canon(b));

const PATH_SAFE = /^urn:pubid:[A-Za-z0-9._~,()\-:]+$/;
const pathSafe = (urn) =>
  PATH_SAFE.test(urn) && !urn.includes("::") && !urn.endsWith(":");

let grandOk = 0;
let grandFail = 0;
const failureLines = [];
const table = [];
const seen = new Map(); // urn -> canonical hash key (injectivity, global)

for (const entry of readdirSync(testsDir).sort()) {
  const dir = join(testsDir, entry);
  if (!statSync(dir).isDirectory()) continue;

  const rows = [];
  for (const file of readdirSync(dir).sort()) {
    if (!file.endsWith(".yaml") || file.startsWith("_")) continue;
    const doc = parseYaml(readFileSync(join(dir, file), "utf8"));
    if (!Array.isArray(doc)) continue;
    for (const row of doc) {
      if (row.identifier !== undefined && row.identifier !== null) {
        rows.push(row);
      }
    }
  }

  let ok = 0;
  const flavorFailures = [];
  const parityRows = parity?.[entry]?.rows;
  const parityById = new Map((parityRows ?? []).map((r) => [r.id, r]));
  let parityChecked = 0;

  // The stale-pending tripwire: a flavor in BUILD_PENDING must have no
  // registered identifier class. When its model lands, this fails and
  // forces the entry off the list — a pending case that passes is an
  // alarm, never a marker left to rot.
  if (BUILD_PENDING.has(entry)) {
    const ported = rows.some((row) => resolveType(row.identifier["_type"]) !== undefined);
    if (ported) {
      flavorFailures.push(
        `${entry}: the identifier class is registered now — remove it from BUILD_PENDING`,
      );
    }
  }

  for (const row of rows) {
    const { id } = row;
    const hash = hashOverrides[row.id] ?? row.identifier;
    try {
      const urn = generate(hash);

      if (!pathSafe(urn)) {
        flavorFailures.push(`${id}: not path-safe: ${urn}`);
      } else {
        const key = JSON.stringify(canon(hash));
        const prior = seen.get(urn);
        if (prior !== undefined && prior !== key) {
          flavorFailures.push(`${id}: collision on ${urn}`);
        } else {
          seen.set(urn, key);
        }
      }

      const back = new Decoder(urn.slice(PREFIX.length)).toIdentifierHash();
      if (!same(back, hash)) {
        flavorFailures.push(
          `${id}: ${urn} -> ${JSON.stringify(canon(back)).slice(0, 160)}`,
        );
      } else if (!SLOW && !BUILD_PENDING.has(entry) && !REBUILD_PENDING.has(id)) {
        // (c)+(f): the canonical rebuild through fromHash, then the slug
        // round-trip. BUILD_PENDING flavors skip both until their model
        // lands; (a),(b),(d),(e) above still ran for them.
        const rebuilt = parse(urn);
        const reUrn = generate(rebuilt.toHash());
        if (reUrn !== urn) {
          flavorFailures.push(`${id}: non-canonical rebuild ${reUrn}`);
        } else {
          const slug = toSlug(urn);
          const slugId = fromSlug(slug);
          if (generate(slugId.toHash()) !== urn) {
            flavorFailures.push(`${id}: slug round-trip broke on ${slug}`);
          } else {
            ok += 1;
          }
        }
      } else {
        ok += 1;
      }

      if (parityRows !== undefined) {
        const expected = parityById.get(id);
        if (expected === undefined) {
          flavorFailures.push(`${id}: missing from the ruby parity fixture`);
        } else if (expected.urn !== urn) {
          flavorFailures.push(
            `${id}: parity ${urn} != ruby ${expected.urn}`,
          );
        } else {
          parityChecked += 1;
        }
      }
    } catch (e) {
      flavorFailures.push(`${id}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }

  grandOk += ok;
  grandFail += flavorFailures.length;
  failureLines.push(
    ...flavorFailures.slice(0, 12).map((line) => `${entry}: ${line}`),
  );
  table.push(
    `${entry.padEnd(12)} ${String(ok).padStart(6)} green` +
      (flavorFailures.length > 0
        ? `  /  ${flavorFailures.length} FAIL`
        : "") +
      (parityRows !== undefined ? `  (parity ${parityChecked})` : "") +
      (rows.length === 0 ? "  (no identifier rows)" : ""),
  );
}

console.log(table.join("\n"));
console.log(
  `\ntotal: ${grandOk} green, ${grandFail} failed` +
    (parity ? ", parity vs ruby checked" : ""),
);
if (failureLines.length > 0) {
  console.log(`\nfirst failures:\n${failureLines.slice(0, 40).join("\n")}`);
  process.exit(1);
}
